(5237782, 760397, 100646, '<td valign="top">this is a really nice shot, but this looks white to me. Perhaps if you played around with your white balance presets you could have gotten the horse to look a little grey.</td>', 'this is a really nice shot, but this looks white to me. Perhaps if you played around with your white balance presets you could have gotten the horse to look a little grey.', '2009-02-03 21:35:13.000000', NULL, 1),
(5237785, 762021, 100646, '<td valign="top">the cropping on this doesnt look right.</td>', 'the cropping on this doesnt look right.', '2009-02-03 21:35:51.000000', NULL, 1),
(5237786, 760415, 100318, '<td valign="top">Great contrast with the yellow eyes.</td>', 'Great contrast with the yellow eyes.', '2009-02-03 21:36:07.000000', NULL, 1),
(5237794, 761928, 100646, '<td valign="top">very nice shot. I kinda wonder if you could have gotten rid of the reflection in her eyes with a polarizing filter.</td>', 'very nice shot. I kinda wonder if you could have gotten rid of the reflection in her eyes with a polarizing filter.', '2009-02-03 21:38:00.000000', NULL, 1),
(5237803, 761486, 100646, '<td valign="top">awesome idea! really creative.</td>', 'awesome idea! really creative.', '2009-02-03 21:41:41.000000', NULL, 1),
(5237805, 761902, 100646, '<td valign="top">this looks more sepia than grey. and if something is grey I''m not really seeing it. Other than not really meeting the challenge I think its a nice picture.</td>', 'this looks more sepia than grey. and if something is grey I''m not really seeing it. Other than not really meeting the challenge I think its a nice picture.', '2009-02-03 21:42:43.000000', NULL, 1),
(5237807, 762020, 100646, '<td valign="top">I find the bright edges on the droplet really distracting.</td>', 'I find the bright edges on the droplet really distracting.', '2009-02-03 21:43:55.000000', NULL, 1),
(5237810, 760714, 94815, '<td valign="top">Excellent, and one of the few that is convincingly on topic without manipulation and well photographed.</td>', 'Excellent, and one of the few that is convincingly on topic without manipulation and well photographed.', '2009-02-03 21:44:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5237814, 762018, 100646, '<td valign="top">I''m seeing gold here, not much silver...no grey.</td>', 'I''m seeing gold here, not much silver...no grey.', '2009-02-03 21:45:44.000000', NULL, 1),
(5237820, 760519, 100646, '<td valign="top">I like the way you framed this one. Nice job getting a good expression on the bird to.</td>', 'I like the way you framed this one. Nice job getting a good expression on the bird to.', '2009-02-03 21:47:11.000000', NULL, 1),
(5237821, 761807, 100646, '<td valign="top">This is really chaotic.</td>', 'This is really chaotic.', '2009-02-03 21:47:48.000000', NULL, 1),
(5237824, 761605, 100646, '<td valign="top">I like the pattern, but the lack of a subject makes the photo sort of uninteresting</td>', 'I like the pattern, but the lack of a subject makes the photo sort of uninteresting', '2009-02-03 21:48:23.000000', NULL, 1),
(5237829, 761280, 100646, '<td valign="top">that pink backdrop almost hurts my eyes. The fact that there is something grey there is negated by the fact that I cant even scan the picture without having to look away and let my eyes rest.</td>', 'that pink backdrop almost hurts my eyes. The fact that there is something grey there is negated by the fact that I cant even scan the picture without having to look away and let my eyes rest.', '2009-02-03 21:49:59.000000', NULL, 1),
(5237830, 761556, 100318, '<td valign="top">I think this photo matches the challenge the best.</td>', 'I think this photo matches the challenge the best.', '2009-02-03 21:50:12.000000', NULL, 1),
(5237834, 761516, 100646, '<td valign="top">this may be a little bit grey, but when put with the white snow it all just looks white.</td>', 'this may be a little bit grey, but when put with the white snow it all just looks white.', '2009-02-03 21:51:20.000000', NULL, 1),
(5237838, 760880, 100318, '<td valign="top">Great picture - it looks so huge.</td>', 'Great picture - it looks so huge.', '2009-02-03 21:52:58.000000', NULL, 1),
(5237849, 762009, 100646, '<td valign="top">thats kinda creepy.</td>', 'thats kinda creepy.', '2009-02-03 21:57:37.000000', NULL, 1),
(5237851, 761784, 100646, '<td valign="top">dont see any grey.</td>', 'dont see any grey.', '2009-02-03 21:58:22.000000', NULL, 1),
(5237858, 761328, 100646, '<td valign="top">The title doesnt make much sense compared to whats actually in the photo.</td>', 'The title doesnt make much sense compared to whats actually in the photo.', '2009-02-03 22:00:51.000000', NULL, 1),
(5237859, 761335, 8759, '<td valign="top">It''s a funny one. Would have been great to have only the birds and the snow. Anyway 7 from me. Tiberius</td>', 'It''s a funny one. Would have been great to have only the birds and the snow. Anyway 7 from me. Tiberius', '2009-02-03 22:00:55.000000', NULL, 1),
(5238071, 761444, 98771, '<td valign="top">Very well done. From what I''ve seen so far, this has to be close to the top of the heap.</td>', 'Very well done. From what I''ve seen so far, this has to be close to the top of the heap.', '2009-02-03 23:41:13.000000', NULL, 1),
(5238808, 761224, 15711, '<td valign="top">I love this.  Too many are black and white and to me, this challenge called for a color shot of grey, and you did it well. Beautiful DOF.</td>', 'I love this.  Too many are black and white and to me, this challenge called for a color shot of grey, and you did it well. Beautiful DOF.', '2009-02-04 09:02:04.000000', NULL, 1),
(5238819, 760880, 15711, '<td valign="top">This is exquisite. I''m trying to figure out if this is a color or BW shot. Well, I guess if I can''t tell,it shouldn''t matter - it''s fabulous.</td>', 'This is exquisite. I''m trying to figure out if this is a color or BW shot. Well, I guess if I can''t tell,it shouldn''t matter - it''s fabulous.', '2009-02-04 09:06:15.000000', NULL, 1),
(5238824, 761907, 15711, '<td valign="top">Cute shoes. Nice stock photo.</td>', 'Cute shoes. Nice stock photo.', '2009-02-04 09:06:59.000000', NULL, 1),
(5238826, 761325, 15711, '<td valign="top">Nice stock type image.  I wish the SUV were tack sharp  but the overall composition and use of "meeting the challenge" really works for me. 7</td>', 'Nice stock type image.  I wish the SUV were tack sharp  but the overall composition and use of "meeting the challenge" really works for me. 7', '2009-02-04 09:08:03.000000', NULL, 1),
(5238827, 760415, 15711, '<td valign="top">And then they announce "Pet Portrait." LOL</td>', 'And then they announce "Pet Portrait." LOL', '2009-02-04 09:08:36.000000', NULL, 1),
(5238834, 761306, 15711, '<td valign="top">I think this is lovely but reading "avoid extreme shades of gray " makes me wonder if it truly follows the rules. Isn''t black and extreme shade of gray?? Nonetheless, it is a beautiful vista and you captured it well.</td>', 'I think this is lovely but reading "avoid extreme shades of gray " makes me wonder if it truly follows the rules. Isn''t black and extreme shade of gray?? Nonetheless, it is a beautiful vista and you captured it well.', '2009-02-04 09:10:34.000000', NULL, 1),
(5238840, 761969, 15711, '<td valign="top">Love the blur.  This is kinda artsy. I might have cropped out the railing on the right.</td>', 'Love the blur.  This is kinda artsy. I might have cropped out the railing on the right.', '2009-02-04 09:11:47.000000', NULL, 1),
(5238841, 760457, 15711, '<td valign="top">Kind of fairy tale feeling. I like the composition. It has an overall green cast on my monitor.</td>', 'Kind of fairy tale feeling. I like the composition. It has an overall green cast on my monitor.', '2009-02-04 09:12:40.000000', NULL, 1),
(5238843, 760899, 15711, '<td valign="top">Very bucolic. I like it.</td>', 'Very bucolic. I like it.', '2009-02-04 09:13:02.000000', NULL, 1),
(5238847, 761928, 15711, '<td valign="top">This is beautiful. Love the softness of the face and the tack sharp eyes.  Well done.</td>', 'This is beautiful. Love the softness of the face and the tack sharp eyes.  Well done.', '2009-02-04 09:14:31.000000', NULL, 1),
(5238850, 761932, 15711, '<td valign="top">ROFL  You a a nut!!!</td>', 'ROFL  You a a nut!!!', '2009-02-04 09:17:06.000000', NULL, 1),
(5238857, 759871, 15711, '<td valign="top">This is outstanding, but I have read and re-read the description and to me it should be a color photo with grey.  Am I wrong?</td>', 'This is outstanding, but I have read and re-read the description and to me it should be a color photo with grey.  Am I wrong?', '2009-02-04 09:27:34.000000', NULL, 1),
(5238860, 760397, 15711, '<td valign="top">I love the frosty nose. Wish his ears weren''t cropped off or you cropped it down further by his forelock. :~)</td>', 'I love the frosty nose. Wish his ears weren''t cropped off or you cropped it down further by his forelock. :~)', '2009-02-04 09:28:43.000000', NULL, 1),
(5238861, 760704, 15711, '<td valign="top">I like the focus and DOF. Nice.</td>', 'I like the focus and DOF. Nice.', '2009-02-04 09:30:13.000000', NULL, 1),
(5238904, 762021, 47470, '<td valign="top">The crop seems a little tight on the top.</td>', 'The crop seems a little tight on the top.', '2009-02-04 10:04:00.000000', NULL, 1),
(5238915, 761679, 47470, '<td valign="top">I''m not sure I like how the tight crop cuts off parts of the bucket.</td>', 'I''m not sure I like how the tight crop cuts off parts of the bucket.', '2009-02-04 10:07:47.000000', NULL, 1),
(5238920, 761909, 47470, '<td valign="top">A little dark, but cool idea/interpretation!</td>', 'A little dark, but cool idea/interpretation!', '2009-02-04 10:08:37.000000', NULL, 1),
(5238927, 762044, 47470, '<td valign="top">I don''t think I would have realized this was a bench if I didn''t read the title.  This is a great subject, but maybe the crop is a little too tight for the viewers to understand what it is without the title.</td>', 'I don''t think I would have realized this was a bench if I didn''t read the title.  This is a great subject, but maybe the crop is a little too tight for the viewers to understand what it is without the title.', '2009-02-04 10:11:05.000000', NULL, 1),
(5239004, 760515, 47470, '<td valign="top">I think I would have tilted the image a bit to straighten out the trees.</td>', 'I think I would have tilted the image a bit to straighten out the trees.', '2009-02-04 10:49:36.000000', NULL, 1),
(5239015, 761325, 47470, '<td valign="top">Looks like it came straight from a magazine.  Great lighting.  I love the inclusion of the signs.</td>', 'Looks like it came straight from a magazine.  Great lighting.  I love the inclusion of the signs.', '2009-02-04 10:53:38.000000', NULL, 1),
(5239536, 761928, 78887, '<td valign="top">Nice sharp image!  I love the detail of the eyes and how smooth the image seems.</td>', 'Nice sharp image!  I love the detail of the eyes and how smooth the image seems.', '2009-02-04 16:29:04.000000', NULL, 1),
(5240183, 761831, 102505, '<td valign="top">Woah....Echoes....</td>', 'Woah....Echoes....', '2009-02-05 00:37:34.000000', NULL, 1),
(5240200, 761947, 102505, '<td valign="top">VERY interesting shot.</td>', 'VERY interesting shot.', '2009-02-05 00:47:49.000000', NULL, 1),
(5240203, 761325, 102505, '<td valign="top">This looks too good to be true. Wonderful mastery of your lighting and composition!</td>', 'This looks too good to be true. Wonderful mastery of your lighting and composition!', '2009-02-05 00:48:53.000000', NULL, 1),
(5240209, 761969, 94283, '<td valign="top">perfectly gray concept.. congratulation</td>', 'perfectly gray concept.. congratulation', '2009-02-05 00:59:10.000000', NULL, 1),
(5240500, 761788, 75192, '<td valign="top">A great gray picture - the rocks and the animals fur. Nice contrast. Border is a bit OTT though.</td>', 'A great gray picture - the rocks and the animals fur. Nice contrast. Border is a bit OTT though.', '2009-02-05 08:37:09.000000', NULL, 1),
(5240695, 761315, 54446, '<td valign="top">Wonderful tones.  Meets the challenge well!  9</td>', 'Wonderful tones.  Meets the challenge well!  9', '2009-02-05 11:25:06.000000', NULL, 1),
(5241047, 761328, 46885, '<td valign="top">Technically competent, but choice of focus is left unexplained</td>', 'Technically competent, but choice of focus is left unexplained', '2009-02-05 15:10:00.000000', NULL, 1),
(5241048, 762039, 46885, '<td valign="top">Not a single element of the picture is in focus and some portion of the biggest pearl doesn''t count as it''s surface-less...</td>', 'Not a single element of the picture is in focus and some portion of the biggest pearl doesn''t count as it''s surface-less...', '2009-02-05 15:10:44.000000', NULL, 1),
(5241052, 761785, 46885, '<td valign="top">Nice pattern, but why did you need to single out some bits out of the desaturated mass of the slates?</td>', 'Nice pattern, but why did you need to single out some bits out of the desaturated mass of the slates?', '2009-02-05 15:11:47.000000', NULL, 1),
(5241055, 761932, 46885, '<td valign="top">Doesn''t look too old for me, so hope for better. A bit too much work on the shadow bit under the chin.</td>', 'Doesn''t look too old for me, so hope for better. A bit too much work on the shadow bit under the chin.', '2009-02-05 15:12:41.000000', NULL, 1),
(5241057, 761854, 46885, '<td valign="top">The tear is very artificial. I recommend honey - can be shaped into different size of tears or wet marks.</td>', 'The tear is very artificial. I recommend honey - can be shaped into different size of tears or wet marks.', '2009-02-05 15:14:24.000000', NULL, 1),
(5241059, 761280, 46885, '<td valign="top">I know how you feel. I would place it onto a better background - surely there are more mismatched socks in your household?</td>', 'I know how you feel. I would place it onto a better background - surely there are more mismatched socks in your household?', '2009-02-05 15:15:21.000000', NULL, 1),
(5241062, 761431, 46885, '<td valign="top">If this is gray then I think you need to check your monitor or your eyes. This is a rather vivid shade of blue, isn''t it?</td>', 'If this is gray then I think you need to check your monitor or your eyes. This is a rather vivid shade of blue, isn''t it?', '2009-02-05 15:16:57.000000', NULL, 1),
(5241068, 759931, 46885, '<td valign="top">I think it''s a good picture in colour. But because of the lack of contrast in the original shot, desaturated version doesn''t work.</td>', 'I think it''s a good picture in colour. But because of the lack of contrast in the original shot, desaturated version doesn''t work.', '2009-02-05 15:19:40.000000', NULL, 1),
(5241072, 760714, 46885, '<td valign="top">Very good not only in colour but in framing.</td>', 'Very good not only in colour but in framing.', '2009-02-05 15:22:37.000000', NULL, 1),
(5241077, 761543, 46885, '<td valign="top">Good idea, focusing and detail, but a strange angle. Why wouldn''t you shoot the collection head on straight?</td>', 'Good idea, focusing and detail, but a strange angle. Why wouldn''t you shoot the collection head on straight?', '2009-02-05 15:24:37.000000', NULL, 1),
(5241114, 760470, 30896, '<td valign="top">I could appreciate the narrow focus, but here it is somehow misplaced, with two different parts of the picture asking for attention in the same time.</td>', 'I could appreciate the narrow focus, but here it is somehow misplaced, with two different parts of the picture asking for attention in the same time.', '2009-02-05 15:46:55.000000', NULL, 1),
(5241124, 761813, 30896, '<td valign="top">Nice one, though I would tone down the skin to make it more greyish, just slightly, as it is a tad too warm. Also the light should be softer probably, though I have never achieved a soft light, so it is hard for me to give any advice :)</td>', 'Nice one, though I would tone down the skin to make it more greyish, just slightly, as it is a tad too warm. Also the light should be softer probably, though I have never achieved a soft light, so it is hard for me to give any advice :)', '2009-02-05 15:52:30.000000', NULL, 1),
(5241132, 761509, 30896, '<td valign="top">may be a too large a crop? a nice pigeon, composition is ok, but the lack of detail spoils the picture</td>', 'may be a too large a crop? a nice pigeon, composition is ok, but the lack of detail spoils the picture', '2009-02-05 15:58:15.000000', NULL, 1),
(5241192, 759871, 35947, '<td valign="top">One of my fav''s in the challenge.</td>', 'One of my fav''s in the challenge.', '2009-02-05 16:27:20.000000', NULL, 1),
(5241194, 760137, 35947, '<td valign="top">Great image. 9</td>', 'Great image. 9', '2009-02-05 16:28:25.000000', NULL, 1),
(5241195, 761941, 35947, '<td valign="top">Great POV/angle.</td>', 'Great POV/angle.', '2009-02-05 16:28:51.000000', NULL, 1),
(5241197, 760457, 35947, '<td valign="top">This has a fairy tale feel to it. 9</td>', 'This has a fairy tale feel to it. 9', '2009-02-05 16:29:26.000000', NULL, 1),
(5241199, 761904, 35947, '<td valign="top">This is so creative!</td>', 'This is so creative!', '2009-02-05 16:30:01.000000', NULL, 1),
(5241202, 761881, 35947, '<td valign="top">Beautiful image!  The lighting is so perfect.</td>', 'Beautiful image!  The lighting is so perfect.', '2009-02-05 16:30:42.000000', NULL, 1),
(5241209, 761486, 35947, '<td valign="top">Creative &amp;  well executed.</td>', 'Creative &  well executed.', '2009-02-05 16:33:59.000000', NULL, 1),
(5241284, 761325, 35947, '<td valign="top">Back to comment...<br/>Really great shot!  I could easily see this in a magazine!</td>', 'Back to comment...Really great shot!  I could easily see this in a magazine!', '2009-02-05 17:54:37.000000', NULL, 1),
(5241426, 761780, 59276, '<td valign="top">I want to say Geena Davis.</td>', 'I want to say Geena Davis.', '2009-02-05 19:18:54.000000', NULL, 1),
(5241442, 760519, 59276, '<td valign="top">beautiful!!!! very well done!!!</td>', 'beautiful!!!! very well done!!!', '2009-02-05 19:26:06.000000', NULL, 1),
(5241446, 761280, 59276, '<td valign="top">IMHO you might have scored higher with a grey background.......The pink is glowing!</td>', 'IMHO you might have scored higher with a grey background.......The pink is glowing!', '2009-02-05 19:28:46.000000', NULL, 1),
(5241452, 761306, 59276, '<td valign="top">wow your foreground looks like cutouts......very surreal</td>', 'wow your foreground looks like cutouts......very surreal', '2009-02-05 19:30:09.000000', NULL, 1),
(5241573, 761865, 94815, '<td valign="top">Seems a bit too dark but truly grey.</td>', 'Seems a bit too dark but truly grey.', '2009-02-05 21:13:27.000000', NULL, 1),
(5241574, 760137, 94815, '<td valign="top">What a lovely set of drawing pencils. Im giving a 7 for its unmanipulated color and topical execution.</td>', 'What a lovely set of drawing pencils. Im giving a 7 for its unmanipulated color and topical execution.', '2009-02-05 21:14:57.000000', NULL, 1),
(5241730, 761815, 31738, '<td valign="top">One of my favorites...10</td>', 'One of my favorites...10', '2009-02-05 23:10:24.000000', NULL, 1),
(5241926, 761989, 103559, '<td valign="top">Very nice photo! Love the composition, the depth of detail in the skin and tusk. Would like to see it against a solid background, may even add more punch to the elephant''s textures.</td>', 'Very nice photo! Love the composition, the depth of detail in the skin and tusk. Would like to see it against a solid background, may even add more punch to the elephant''s textures.', '2009-02-06 02:56:44.000000', NULL, 1),
(5241927, 761780, 103559, '<td valign="top">It''s an interesting idea. I''m thinking it''s Marilyn?! A little too mono-chromatic for me, gets a bit muddied leaning to browns over gray.</td>', 'It''s an interesting idea. I''m thinking it''s Marilyn?! A little too mono-chromatic for me, gets a bit muddied leaning to browns over gray.', '2009-02-06 02:58:34.000000', NULL, 1),
(5241928, 760885, 103559, '<td valign="top">Very well exposed, nice tonal range. Disturbing look in his eyes captured emotion well!</td>', 'Very well exposed, nice tonal range. Disturbing look in his eyes captured emotion well!', '2009-02-06 02:59:42.000000', NULL, 1),
(5241930, 761927, 103559, '<td valign="top">This is a beautiful shot, crisp where it should be and soft to add depth and background. I don''t see it as very ''grey'' though, colors seem more brownish, orangy, white to me.</td>', 'This is a beautiful shot, crisp where it should be and soft to add depth and background. I don''t see it as very ''grey'' though, colors seem more brownish, orangy, white to me.', '2009-02-06 03:01:27.000000', NULL, 1),
(5241931, 760397, 103559, '<td valign="top">That''s a LOVELY shot! Very nice portrait, great depth of field and sense of place. Well composed!</td>', 'That''s a LOVELY shot! Very nice portrait, great depth of field and sense of place. Well composed!', '2009-02-06 03:02:13.000000', NULL, 1),
(5241932, 761473, 103559, '<td valign="top">Interesting idea but too posed for me. Would be more interesting in it''s ''natural habitat''.</td>', 'Interesting idea but too posed for me. Would be more interesting in it''s ''natural habitat''.', '2009-02-06 03:02:50.000000', NULL, 1),
(5241934, 761917, 103559, '<td valign="top">Great light on the subject, the eyes, the wings. Would have been much more dramatic/more depth of field if background was really out of focus. Right now bright spots in the leaves are fighting with the bird for attention.</td>', 'Great light on the subject, the eyes, the wings. Would have been much more dramatic/more depth of field if background was really out of focus. Right now bright spots in the leaves are fighting with the bird for attention.', '2009-02-06 03:05:01.000000', NULL, 1),
(5241935, 761932, 103559, '<td valign="top">Caption really helps this image out! Could be a successful greeting card.</td>', 'Caption really helps this image out! Could be a successful greeting card.', '2009-02-06 03:05:58.000000', NULL, 1),
(5241938, 760899, 103559, '<td valign="top">Gorgeous. Surreal looking. However, I''m wondering how much manipulation went into producing the shot though. Foreground looks too blurred to have been shot that way. A bit much.</td>', 'Gorgeous. Surreal looking. However, I''m wondering how much manipulation went into producing the shot though. Foreground looks too blurred to have been shot that way. A bit much.', '2009-02-06 03:07:46.000000', NULL, 1),
(5241940, 761853, 103559, '<td valign="top">Very well done. Nice depth of field just in the face alone.</td>', 'Very well done. Nice depth of field just in the face alone.', '2009-02-06 03:08:19.000000', NULL, 1),
(5241944, 761788, 103559, '<td valign="top">I actually find myself focusing on the beauty and interesting textures, color and lighting of the rocks more than the sheep. Would be nice to see the image without the sheep, as strange as that may sound. Overall a nice portrait, well placed subject.</td>', 'I actually find myself focusing on the beauty and interesting textures, color and lighting of the rocks more than the sheep. Would be nice to see the image without the sheep, as strange as that may sound. Overall a nice portrait, well placed subject.', '2009-02-06 03:10:04.000000', NULL, 1),
(5241950, 761145, 103559, '<td valign="top">Good eye for unique subject matter; however, there''s too much going on in one shot. Would have LOVED it if you had lowered your camera down and captured just the bottom half of the image as a full frame shot! Or found a way to shoot around the trees, for me they add more chaos and clutter to the image then anything.</td>', 'Good eye for unique subject matter; however, there''s too much going on in one shot. Would have LOVED it if you had lowered your camera down and captured just the bottom half of the image as a full frame shot! Or found a way to shoot around the trees, for me they add more chaos and clutter to the image then anything.', '2009-02-06 03:13:24.000000', NULL, 1),
(5241952, 761782, 103559, '<td valign="top">Beautiful shot; however, I don''t really see this image as ''grey'' since the focus and the light are on the bottom right corner of the scene, a gorgeous rich brownish/purple/orange of the land. My eye goes there.</td>', 'Beautiful shot; however, I don''t really see this image as ''grey'' since the focus and the light are on the bottom right corner of the scene, a gorgeous rich brownish/purple/orange of the land. My eye goes there.', '2009-02-06 03:15:02.000000', NULL, 1),
(5241956, 761213, 103559, '<td valign="top">Very striking shot, excellent intricate details. Would have REALLY been superb if there was a way to shoot around the lamp post. It doesn''t add anything to the picture, it takes away from the statue''s stark silhoette.</td>', 'Very striking shot, excellent intricate details. Would have REALLY been superb if there was a way to shoot around the lamp post. It doesn''t add anything to the picture, it takes away from the statue''s stark silhoette.', '2009-02-06 03:16:30.000000', NULL, 1),
(5241957, 760635, 103559, '<td valign="top">Cute! Unique. Interesting, just unfortunate that the subject is not sharp. Would really like to see the elephant in focus, at least a part of it, say the eye or the snout. Fun though.</td>', 'Cute! Unique. Interesting, just unfortunate that the subject is not sharp. Would really like to see the elephant in focus, at least a part of it, say the eye or the snout. Fun though.', '2009-02-06 03:17:47.000000', NULL, 1),
