(5241979, 761901, 103559, '<td valign="top">VERY interesting portrait! Tells an entire story, don''t need any more detail in the face! I sense an old sea captian in a cold place, who has been through the ringer... WELL DONE!</td>', 'VERY interesting portrait! Tells an entire story, don''t need any more detail in the face! I sense an old sea captian in a cold place, who has been through the ringer... WELL DONE!', '2009-02-06 03:38:52.000000', NULL, 1),
(5241980, 761898, 103559, '<td valign="top">Interesting patterns, well exposed, excellent textures, detail captured. Subject matter may have been stronger, had you just shot the shingles and concentrated on the abstract pattern alone.</td>', 'Interesting patterns, well exposed, excellent textures, detail captured. Subject matter may have been stronger, had you just shot the shingles and concentrated on the abstract pattern alone.', '2009-02-06 03:39:59.000000', NULL, 1),
(5241982, 761958, 103559, '<td valign="top">Great color contrast. Strong lines, geometry, shapes in the composition. Too blurry though. Nothing''s in focus.</td>', 'Great color contrast. Strong lines, geometry, shapes in the composition. Too blurry though. Nothing''s in focus.', '2009-02-06 03:40:48.000000', NULL, 1),
(5241983, 760190, 103559, '<td valign="top">EXCELLENT. Would be a very strong advertising photo, greeting card cover. Fantastic detail, sharpness. Well done.</td>', 'EXCELLENT. Would be a very strong advertising photo, greeting card cover. Fantastic detail, sharpness. Well done.', '2009-02-06 03:42:08.000000', NULL, 1),
(5241984, 761876, 103559, '<td valign="top">Interesting concept/idea. Not crazy about the composition though. Don''t know myself how it could have been shot better, but there''s something about the angle, flatness of the lighting that''s not helping the image out. Could be more striking perhaps from a different angle, better lit.</td>', 'Interesting concept/idea. Not crazy about the composition though. Don''t know myself how it could have been shot better, but there''s something about the angle, flatness of the lighting that''s not helping the image out. Could be more striking perhaps from a different angle, better lit.', '2009-02-06 03:43:47.000000', NULL, 1),
(5241985, 761964, 103559, '<td valign="top">EXCELLENT SHOT! Highly dramatic. Great composition, use of positive and negative space. Well lit. Would make a fantastic film poster!</td>', 'EXCELLENT SHOT! Highly dramatic. Great composition, use of positive and negative space. Well lit. Would make a fantastic film poster!', '2009-02-06 03:45:00.000000', NULL, 1),
